// Chess rules for this board: the move log, captures, and pawn promotion.
// Attached to the board. Table scripts run on the host only, and `globalEvents`
// works from an object script as well as a scene script.

type Side = "white" | "black";
type Promotion = "queen" | "rook" | "bishop" | "knight";
type Cell = { col: number; row: number };

const PITCH = 0.174; // square pitch on this board, in feet
const CAPTURE_ZONE_NAME = "CaptureZone";
const PROMOTIONS: readonly Promotion[] = ["queen", "rook", "bishop", "knight"];
/** Seats are colour ids; the "White" / "Black" nameplates are only labels. */
const SEAT_BY_SIDE: Record<Side, string> = { white: "blue", black: "red" };

const liftedFrom = new Map<string, Vec3>(); // piece id -> where it was picked up
const captureZones = new Map<Side, SeatZoneInfo>(); // zones are fixed for a game, so cache them
let boardOrigin: Vec3 | null = null; // the board is locked, so cache it too

// ---- Setup -------------------------------------------------------------------------

PROMOTIONS.forEach((piece, order) => {
  world.addObjectMenuItem({
    id: `promote-${piece}`,
    label: `Promote to ${piece.charAt(0).toUpperCase()}${piece.slice(1)}`,
    match: { tags: ["pawn"] },
    order
  });
});

world.log("[chess] rules loaded");

// ---- Events ------------------------------------------------------------------------

globalEvents.onObjectPickedUp.add((object) => {
  if (object.tags.includes("piece")) liftedFrom.set(object.id, object.position);
});

globalEvents.onObjectDropped.add((object, context) => {
  // Pieces this script moves (captures, promotions) are not a player's move.
  if (context.actor === "Script" || !object.tags.includes("piece")) return;
  void onPlayerMove(object, context);
});

globalEvents.onObjectMenuItem.add((object, itemId, context) => {
  const piece = PROMOTIONS.find((p) => itemId === `promote-${p}`);
  if (piece) void promote(object, piece, context);
});

// ---- Moves and captures --------------------------------------------------------------

async function onPlayerMove(mover: ObjectHandle, context: EventContext): Promise<void> {
  // Read the drop position before anything awaits. A handle updates as later snapshots
  // arrive, and within a few frames the two pieces' hulls push a capturer about two thirds
  // of a square off its victim.
  const dropPos = mover.position;
  const start = liftedFrom.get(mover.id);
  liftedFrom.delete(mover.id);

  const captured = await resolveCapture(mover, dropPos);
  const [from, to] = await Promise.all([
    start ? world.getSnapPointAt(start) : Promise.resolve(null),
    world.getSnapPointAt(dropPos)
  ]);
  if (from && to && from.id === to.id) return; // picked up and put back

  const capture = captured ? `, capturing ${captured}` : "";
  world.log(
    `${playerName(context.actor)} moved ${nameOf(mover)} from ${from?.label ?? "off the board"}`
      + ` to ${to?.label ?? "off the board"}${capture}`
  );
}

/** Sends an enemy piece on the drop square to the capturer's zone. Returns its name, or null. */
async function resolveCapture(mover: ObjectHandle, dropPos: Vec3): Promise<string | null> {
  const attacker = sideOf(mover);
  const origin = await getBoardOrigin();
  if (!attacker || !origin) return null;
  const square = cellOf(dropPos, origin);
  if (!onBoard(square)) return null;

  const pieces = await world.getAllObjects({ tag: "piece" });
  const victim = pieces.find((p) => {
    const side = sideOf(p);
    return p.id !== mover.id && side !== null && side !== attacker && sameCell(cellOf(p.position, origin), square);
  });
  if (!victim) return null;

  // The snap point set the attacker down on the victim, so the victim's spot is the square's
  // centre at board height. Victim out first, then the attacker in: the other order overlaps
  // two pieces and physics shoves them apart.
  const target = victim.position;
  if (!(await sendToCaptureZone(victim, attacker))) return null;
  mover.setPosition([target[0], target[1], target[2]]);
  world.broadcast(`${attacker} captures ${nameOf(victim)}.`);
  return nameOf(victim);
}

/** Moves a captured piece into the capturer's zone. False when that seat has no such zone. */
async function sendToCaptureZone(victim: ObjectHandle, capturer: Side): Promise<boolean> {
  const zone = await getCaptureZone(capturer);
  if (!zone) {
    world.log(`[chess] no "${CAPTURE_ZONE_NAME}" zone on the ${capturer} seat; capture skipped.`);
    return false;
  }
  // Drop it in the middle of the zone, at its current height so it falls onto the table;
  // the zone's grid layout arranges captured pieces from there.
  victim.setPosition([zone.position[0], victim.position[1], zone.position[2]]);
  return true;
}

// ---- Promotion -----------------------------------------------------------------------

/**
 * Replaces a pawn with a queen, rook, bishop or knight of its own colour.
 *
 * The model is copied from a piece of that type already on the table. Captured pieces stay on
 * the table, so one always exists, and nothing depends on asset file names.
 */
async function promote(pawn: ObjectHandle, piece: Promotion, context: EventContext): Promise<void> {
  const side = sideOf(pawn);
  if (!side) return;
  const template = (await world.getAllObjects({ tag: piece })).find((p) => sideOf(p) === side);
  const model = template?.metadata.customModelAssetId;
  if (!template || typeof model !== "string") {
    world.log(`[chess] no ${side} ${piece} on the table to copy; promotion cancelled.`);
    return;
  }

  // Take what the replacement needs, then remove the pawn before spawning so the two bodies
  // never overlap. Scale is copied because the model's sidecar does not carry it.
  const { position, rotation, scale } = pawn;
  pawn.destroy();
  await world.spawnObject({
    kind: template.kind,
    name: template.name ?? `${piece}-${side}`,
    position,
    rotation,
    scale,
    tags: ["piece", side, piece],
    metadata: { customModelAssetId: model }
  });
  world.broadcast(`${playerName(context.actor)} promotes a ${side} pawn to a ${piece}.`);
}

// ---- Helpers -------------------------------------------------------------------------

async function getBoardOrigin(): Promise<Vec3 | null> {
  if (!boardOrigin) {
    boardOrigin = (await world.getAllObjects({ kind: "board" }))[0]?.position ?? null;
  }
  return boardOrigin;
}

/** Only a zone that was found is cached, so one that becomes active later is still picked up. */
async function getCaptureZone(side: Side): Promise<SeatZoneInfo | null> {
  const cached = captureZones.get(side);
  if (cached) return cached;
  const zones = await world.getSeatZones(SEAT_BY_SIDE[side]);
  const zone = zones.find((z) => z.name.toLowerCase() === CAPTURE_ZONE_NAME.toLowerCase()) ?? null;
  if (zone) captureZones.set(side, zone);
  return zone;
}

/** The board square under a position: 0-7 on the board, outside that range off it. */
function cellOf(p: Vec3, origin: Vec3): Cell {
  return {
    col: Math.round((p[0] - origin[0]) / PITCH + 3.5),
    row: Math.round((p[2] - origin[2]) / PITCH + 3.5)
  };
}

function onBoard(c: Cell): boolean {
  return c.col >= 0 && c.col < 8 && c.row >= 0 && c.row < 8;
}

function sameCell(a: Cell, b: Cell): boolean {
  return a.col === b.col && a.row === b.row;
}

function sideOf(piece: ObjectData): Side | null {
  if (piece.tags.includes("white")) return "white";
  if (piece.tags.includes("black")) return "black";
  return null;
}

function nameOf(piece: ObjectData): string {
  return piece.name ?? piece.kind;
}

/** A peer id as the name players see; a non-peer actor ("Script", "You") passes through. */
function playerName(actor: string): string {
  return world.getPlayers().find((p) => p.peerId === actor)?.displayName ?? actor;
}

