const TBL_WHITE = "white";
const TBL_BLACK = "black";
const TBL_SAVE_KEY = "chess";
const TBL_LABEL_ID = "chess-status";
const TBL_MENU_NEW_GAME = "chess-new-game";
const TBL_MENU_ADOPT = "chess-adopt-board";
const TBL_MENU_RESIGN = "chess-resign";
const TBL_MENU_PROMOTE = "chess-promote-";
/** Pieces lie this far above a square's snap point when the script sets them down, in feet. */
const TBL_DROP = 0.01;
/** How long to let a piece settle before the board is read again. */
const TBL_SETTLE_SECONDS = 0.3;
const TBL_KIND_TAGS = ["", "pawn", "knight", "bishop", "rook", "queen", "king"];
const TBL_KIND_NAMES = ["", "pawn", "knight", "bishop", "rook", "queen", "king"];

/** Bot difficulty dials, restated here because a bot the script plays itself is not told its manifest dials. */
const BOT_MINIMAX: Record<string, { depth: number; noise: number }> = {
  easy: { depth: 1, noise: 60 },
  normal: { depth: 2, noise: 10 },
  hard: { depth: 3, noise: 0 }
};
/**
 * The Maia bot: each difficulty is its own network, trained to play like people of that rating
 * (Maia 1100 / 1500 / 1900, CSSLab). It plays the move the network rates likeliest, as Maia is
 * meant to be played (no search); `openingTemperature` varies the first moves so games differ.
 */
const BOT_MAIA: Record<string, { modelId: string }> = {
  easy: { modelId: "maia-1100" },
  medium: { modelId: "maia-1500" },
  hard: { modelId: "maia-1900" }
};
const BOT_MAIA_INPUT = "input__planes";
const BOT_MAIA_POLICY = "output__policy";
const BOT_OPENING_PLIES = 8;
const BOT_OPENING_TEMPERATURE = 1;
/** Pause before a bot the script drives itself moves, so a person can see what happened. */
const BOT_PACE_SECONDS = 0.6;

interface TblSquare {
  cell: number;
  name: string;
  position: Vec3;
  reach: number;
}

interface TblPiece {
  handle: ObjectHandle;
  /** Piece code: 1-6 white, negative black. 0 when the tags do not say. */
  code: number;
