let tblSquares: TblSquare[] | null = null;
let tblSquareSize = 0.17;
/** Plan-view unit vectors along the files (a to h) and the ranks (1 to 8). */
let tblFileAxis: [number, number] = [1, 0];
let tblRankAxis: [number, number] = [0, 1];
let tblCentre: Vec3 = [0, 0, 0];
const tblTemplates: Record<string, TblTemplate> = {};
let game: ChessState | null = null;
/** "" while the game is on; otherwise how it ended ("checkmate", "resigned-white", ...). */
let gameOver = "";
/** The moves of this game in algebraic notation, for the log and the status label. */
let gameMoves: string[] = [];
const gameSeatOf: Record<string, string | null> = { white: null, black: null };
/** The last table reading a notice was given for, so one wrong move is reported once. */
let tblNoticeKey = "";
/** A promotion that can still be changed: the piece, and the position before it. */
let tblPromotion: { pieceId: string; before: ChessState; move: ChessMove } | null = null;
let tblQueue: Promise<void> = Promise.resolve();
/** The bots' number source (variety only: nothing depends on two tables drawing the same numbers). */
let tblSeed = Math.floor(Math.random() * 4294967296) | 0;

function tblRandom(): number {
  tblSeed = (tblSeed + 0x6d2b79f5) | 0;
  let t = tblSeed;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}

function tblDescribe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** Run one table task after the previous one, so a bot move and a person's move never interleave. */
function tblRun<T>(task: () => Promise<T>): Promise<T> {
  const run = tblQueue.then(task);
  tblQueue = run.then(
    () => undefined,
    (error) => { world.log("Chess: " + tblDescribe(error)); }
  );
  return run;
}

function tblColourName(colour: number): string {
  return colour === 1 ? "White" : "Black";
}

function tblColourKey(colour: number): string {
  return colour === 1 ? TBL_WHITE : TBL_BLACK;
}

function tblTemplateKey(code: number): string {
  return (code > 0 ? TBL_WHITE : TBL_BLACK) + "-" + TBL_KIND_TAGS[Math.abs(code)];
}

// ---------------------------------------------------------------- squares -----------

function tblPlanDistance(a: Vec3, b: Vec3): number {
  const dx = a[0] - b[0];
  const dz = a[2] - b[2];
  return Math.sqrt(dx * dx + dz * dz);
}

function tblUnit(dx: number, dz: number): [number, number] {
  const length = Math.sqrt(dx * dx + dz * dz);
  return length > 1e-9 ? [dx / length, dz / length] : [1, 0];
}

function tblDot(v: [number, number], dx: number, dz: number): number {
  return v[0] * dx + v[1] * dz;
}

/** The piece code a set of tags names: 1-6 white, negative black, 0 when it is not a chess piece. */
function tblCodeOf(tags: readonly string[]): number {
  const lower = tags.map((tag) => tag.toLowerCase());
  const colour = lower.indexOf(TBL_WHITE) >= 0 ? 1 : lower.indexOf(TBL_BLACK) >= 0 ? -1 : 0;
  if (colour === 0) return 0;
  for (let kind = 1; kind <= 6; kind += 1) if (lower.indexOf(TBL_KIND_TAGS[kind]) >= 0) return colour * kind;
  return 0;
}

async function tblPieceHandles(): Promise<ObjectHandle[]> {
  const tag = tblSettings.pieceTag.trim();
  const all = tag.length > 0 ? await world.getAllObjects({ tag }) : await world.getAllObjects();
  return all.filter((handle) => tblCodeOf(handle.tags) !== 0);
}

/**
 * Find the 64 squares from where the snap points are (their labels are not trusted: a board may
 * label them any way). The grid's two directions come from the spacing of the points; which way
 * is rank 1 comes from where the white pieces stand (or the saved orientation), and the a-file
 * is on White's left.
 */
async function tblLoadSquares(saved: { file: [number, number]; rank: [number, number] } | null): Promise<boolean> {
  const points = await world.getSnapPoints();
  if (points.length < 64) {
    world.broadcast("Chess: the board needs 64 snap points, one per square (found " + points.length + ").");
    return false;
  }
  let cx = 0;
  let cy = 0;
  let cz = 0;
  for (const point of points) {
    cx += point.position[0] / points.length;
    cy += point.position[1] / points.length;
    cz += point.position[2] / points.length;
  }
  // Spacing and one grid direction from the closest pair of points.
  let pitch = Infinity;
  let axis: [number, number] = [1, 0];
  for (let i = 0; i < points.length; i += 1) {
    for (let j = i + 1; j < points.length; j += 1) {
      const d = tblPlanDistance(points[i].position, points[j].position);
      if (d > 1e-4 && d < pitch) {
        pitch = d;
        axis = tblUnit(points[j].position[0] - points[i].position[0], points[j].position[2] - points[i].position[2]);
      }
    }
  }
  const other: [number, number] = [-axis[1], axis[0]];
  const grid: (SnapPointInfo | null)[] = [];
  for (let i = 0; i < 64; i += 1) grid.push(null);
  for (const point of points) {
    const dx = point.position[0] - cx;
    const dz = point.position[2] - cz;
    const u = Math.round(tblDot(axis, dx, dz) / pitch + 3.5);
    const v = Math.round(tblDot(other, dx, dz) / pitch + 3.5);
    if (u < 0 || u > 7 || v < 0 || v > 7 || grid[v * 8 + u]) continue;
    grid[v * 8 + u] = point;
  }
  if (grid.some((point) => point === null)) {
    world.broadcast("Chess: the snap points do not form an 8 x 8 grid of squares.");
    return false;
  }
  // Which way the ranks run: from White's pieces towards Black's.
  let rank: [number, number] | null = saved ? saved.rank : null;
  if (!rank) {
    let wx = 0;
    let wz = 0;
    let bx = 0;
    let bz = 0;
    let whites = 0;
    let blacks = 0;
    for (const handle of await tblPieceHandles()) {
      const code = tblCodeOf(handle.tags);
      if (code > 0) {
        wx += handle.position[0];
        wz += handle.position[2];
        whites += 1;
      } else {
        bx += handle.position[0];
        bz += handle.position[2];
        blacks += 1;
      }
    }
    if (whites === 0 || blacks === 0) {
      world.broadcast("Chess: cannot tell which side is White's - there are no white or no black pieces on the table.");
      return false;
    }
    const toBlack = tblUnit(bx / blacks - wx / whites, bz / blacks - wz / whites);
    // Snap to whichever grid direction is closer.
    const alongAxis = tblDot(axis, toBlack[0], toBlack[1]);
    const alongOther = tblDot(other, toBlack[0], toBlack[1]);
    rank = Math.abs(alongAxis) >= Math.abs(alongOther)
      ? [axis[0] * Math.sign(alongAxis), axis[1] * Math.sign(alongAxis)]
      : [other[0] * Math.sign(alongOther), other[1] * Math.sign(alongOther)];
  }
  // Facing along the ranks, White's right hand is (-rank.z, rank.x) in plan view: the a-to-h direction.
  let file: [number, number] = [-rank[1], rank[0]];
  if (tblSettings.mirrorFiles) file = [-file[0], -file[1]];
  tblFileAxis = file;
  tblRankAxis = rank;
  tblSquareSize = pitch;
  tblCentre = [cx, cy, cz];
  const squares: TblSquare[] = [];
  for (let cell = 0; cell < 64; cell += 1) {
    const f = (cell & 7) - 3.5;
    const r = (cell >> 3) - 3.5;
    const want: Vec3 = [cx + (file[0] * f + rank[0] * r) * pitch, cy, cz + (file[1] * f + rank[1] * r) * pitch];
    let nearest = grid[0] as SnapPointInfo;
    for (const point of grid) {
      if (point && tblPlanDistance(point.position, want) < tblPlanDistance(nearest.position, want)) nearest = point;
    }
    squares.push({
      cell,
      name: chsSquareName(cell),
      position: [nearest.position[0], nearest.position[1], nearest.position[2]],
      reach: Math.max(nearest.snapRadius, pitch * 0.48)
    });
  }
  tblSquares = squares;
  return true;
}

/** The square a position is on, or -1: the nearest square whose reach holds it, in plan view. */
function tblCellAt(position: Vec3): number {
  if (!tblSquares) return -1;
  let best = -1;
  let bestDistance = Infinity;
  for (const square of tblSquares) {
    const distance = tblPlanDistance(position, square.position);
    if (distance <= square.reach && distance < bestDistance) {
      best = square.cell;
      bestDistance = distance;
    }
  }
  return best;
}

// ---------------------------------------------------------------- reading the table -

async function tblRead(): Promise<TblReading> {
  const pieces: TblPiece[] = [];
  const onCell: TblPiece[][] = [];
  for (let i = 0; i < 64; i += 1) onCell.push([]);
  for (const handle of await tblPieceHandles()) {
    const piece: TblPiece = { handle, code: tblCodeOf(handle.tags), cell: tblCellAt(handle.position) };
    pieces.push(piece);
    if (piece.cell >= 0) onCell[piece.cell].push(piece);
    tblRememberTemplate(handle, piece.code, piece.cell);
  }
  return { pieces, onCell };
}

function tblRememberTemplate(handle: ObjectHandle, code: number, cell: number): void {
  const key = tblTemplateKey(code);
  const model = handle.metadata["customModelAssetId"];
  if (tblTemplates[key] || typeof model !== "string") return;
  const lift = cell >= 0 && tblSquares ? Math.max(0, handle.position[1] - tblSquares[cell].position[1]) : 0.04;
  tblTemplates[key] = {
    kind: handle.kind,
    name: handle.name,
    rotation: [handle.rotation[0], handle.rotation[1], handle.rotation[2]],
    scale: [handle.scale[0], handle.scale[1], handle.scale[2]],
    tags: handle.tags.slice(),
    model,
    lift
  };
}

/**
 * What the board shows, one piece code per square. Where a capture left two pieces on a square,
 * the piece of `mover`'s colour counts (it has just arrived); between two of the mover's own
 * (a king put onto its rook to castle), the king counts.
 */
function tblVisible(reading: TblReading, mover: number): number[] {
  const board: number[] = [];
  for (let cell = 0; cell < 64; cell += 1) {
    const here = reading.onCell[cell];
    if (here.length === 0) {
      board.push(0);
      continue;
    }
    let pick = here[0].code;
    for (const piece of here) {
      const ours = piece.code * mover > 0;
      if (ours && (pick * mover < 0 || Math.abs(piece.code) === CHS_KING)) pick = piece.code;
    }
    board.push(pick);
  }
  return board;
}

function tblBoardsEqual(x: ArrayLike<number>, y: ArrayLike<number>): boolean {
  for (let i = 0; i < 64; i += 1) if (x[i] !== y[i]) return false;
  return true;
}

/**
 * The ways a person's hands can leave the board after making legal move `m`: the whole move,
 * or the move with the parts the script finishes still undone (the rook of a castling, the pawn
 * an en-passant capture takes, the pawn not yet turned into its promotion piece).
 */
function tblHumanOutcomes(s: ChessState, m: ChessMove): number[][] {
  const colour = chsColourToMove(s);
  const from = chsMoveFrom(m, colour);
  const to = chsMoveTo(m, colour);
  const full = chsMakeBoard(s.board, m, colour, s.ep).board;
  const outcomes: number[][] = [full];
  if (chsIsCastle(s.board, m, colour)) {
    const home = from & 56;
    const kingTo = home + (to > from ? 6 : 2);
    const kingOnly = s.board.slice();
    kingOnly[from] = 0;
    kingOnly[kingTo] = colour * CHS_KING;
    outcomes.push(kingOnly);
    const kingOnRook = s.board.slice();
    kingOnRook[from] = 0;
    kingOnRook[to] = colour * CHS_KING;
    outcomes.push(kingOnRook);
  } else if (s.board[from] === colour * CHS_PAWN) {
    if (to === s.ep && s.board[to] === 0) {
      const victimLeft = full.slice();
      victimLeft[to - (colour === 1 ? 8 : -8)] = -colour * CHS_PAWN;
      outcomes.push(victimLeft);
    }
    if ((to >> 3) === 0 || (to >> 3) === 7) {
      // A person's pawn becomes a queen; the menu offers the others afterwards.
      if (chsMovePromo(m) !== 1) return [];
      const pawnLeft = full.slice();
      pawnLeft[to] = colour * CHS_PAWN;
      outcomes.push(pawnLeft);
    }
  }
  return outcomes;
}

// ---------------------------------------------------------------- seats --------------

function tblSeatIsBot(seat: string | null): boolean {
  if (!seat) return false;
  return world.getPlayers().some((player) => player.seat === seat && player.isBot);
}

function tblColourIsBot(colour: number): boolean {
  return tblSeatIsBot(gameSeatOf[tblColourKey(colour)]);
}

/** The seat a person plays from; a person with no seat (any solo table) is "@" + their id. */
function tblSeatOfPeer(peerId: string): string {
  const players = world.getPlayers();
  let found = players.find((player) => player.peerId === peerId);
  if (!found && (peerId === "You" || peerId === "Host" || peerId === "System")) {
    found = players.find((player) => player.isHost);
  }
  return found && found.seat ? found.seat : "@" + peerId;
}

function tblSeatOccupied(seat: string): boolean {
  return world.getPlayers().some((player) => (seat.charAt(0) === "@" ? "@" + player.peerId === seat : player.seat === seat));
}

/** Give `colour` to `seat` unless the colours are already settled (by the settings or by play). */
function tblClaimColour(seat: string | null, colour: number): void {
  if (tblSettings.whiteSeat) gameSeatOf[TBL_WHITE] = tblSettings.whiteSeat;
  if (tblSettings.blackSeat) gameSeatOf[TBL_BLACK] = tblSettings.blackSeat;
  if (!seat) return;
  const key = tblColourKey(colour);
  const other = tblColourKey(-colour);
  if (gameSeatOf[key] === null && gameSeatOf[other] !== seat) gameSeatOf[key] = seat;
  if (gameSeatOf[other] === null && gameSeatOf[key] !== null) {
    const opponent = world.getPlayers().find((player) => player.seat !== null && player.seat !== gameSeatOf[key]);
    if (opponent && opponent.seat) gameSeatOf[other] = opponent.seat;
  }
}

/** The colour a seat plays, claiming the side to move for a seat that has none yet. 0 if it plays neither. */
function tblColourOfSeat(seat: string | null): number {
  if (!game) return 0;
  if (seat !== null && gameSeatOf[TBL_WHITE] === seat) return 1;
  if (seat !== null && gameSeatOf[TBL_BLACK] === seat) return -1;
  tblClaimColour(seat, chsColourToMove(game));
  if (seat !== null && gameSeatOf[TBL_WHITE] === seat) return 1;
  if (seat !== null && gameSeatOf[TBL_BLACK] === seat) return -1;
  return 0;
}

function tblPlayerName(colour: number): string {
  const seat = gameSeatOf[tblColourKey(colour)];
  const player = seat ? world.getPlayers().find((entry) => entry.seat === seat) : undefined;
  const name = player && player.displayName ? player.displayName : "";
  return name.length > 0 ? tblColourName(colour) + " (" + name + ")" : tblColourName(colour);
}

// ---------------------------------------------------------------- saving and status --

interface TblSaved {
  v: number;
  game: ChessState;
  over: string;
  moves: string[];
  white: string | null;
  black: string | null;
  file: [number, number];
  rank: [number, number];
  templates: Record<string, TblTemplate>;
}

async function tblSave(): Promise<void> {
  if (!game) return;
  const saved: TblSaved = {
    v: 1,
    game,
    over: gameOver,
    moves: gameMoves,
    white: gameSeatOf[TBL_WHITE],
    black: gameSeatOf[TBL_BLACK],
    file: tblFileAxis,
    rank: tblRankAxis,
    templates: tblTemplates
  };
  await world.setSavedData(JSON.stringify(saved), TBL_SAVE_KEY);
}

async function tblLoadSaved(): Promise<TblSaved | null> {
  const raw = await world.getSavedData(TBL_SAVE_KEY);
  if (!raw) return null;
  try {
    const data = JSON.parse(raw) as TblSaved;
    const state = data.game;
    if (data.v !== 1 || !state || !Array.isArray(state.board) || state.board.length !== 64) return null;
    if (!Array.isArray(data.file) || !Array.isArray(data.rank)) return null;
    return data;
  } catch (error) {
    return null;
  }
}

function tblEndingLine(): string {
  if (!game) return "";
  const colour = chsColourToMove(game);
  switch (gameOver) {
    case "checkmate": return "Checkmate. " + tblPlayerName(-colour) + " wins.";
    case "stalemate": return "Stalemate. Draw.";
    case "fifty-move": return "Draw by the fifty-move rule.";
    case "repetition": return "Draw by threefold repetition.";
    case "material": return "Draw: neither side can mate.";
    case "resigned-white": return "White resigns. " + tblPlayerName(-1) + " wins.";
    case "resigned-black": return "Black resigns. " + tblPlayerName(1) + " wins.";
    default: return "";
  }
}

function tblRenderStatus(): void {
  if (!game || !tblSquares) return;
  const colour = chsColourToMove(game);
  let line: string;
  if (gameOver !== "") line = tblEndingLine();
  else line = tblColourName(colour) + " to move" + (chsInCheck(game.board, colour) ? " - check!" : "");
  const last = gameMoves.length > 0
    ? "Last: " + String(Math.ceil(gameMoves.length / 2)) + (gameMoves.length % 2 === 1 ? ". " : "... ") + gameMoves[gameMoves.length - 1]
    : "New game";
  // Beside the a-file, turned to read for the side to move - or, against a bot, always for the
  // person (or White once the game is over between two people).
  const offset = (4 + tblSettings.labelDistance) * tblSquareSize;
  const shift = tblSettings.labelShift * tblSquareSize;
  const position: Vec3 = [
    tblCentre[0] - tblFileAxis[0] * offset - tblRankAxis[0] * shift,
    tblCentre[1] + 0.01,
    tblCentre[2] - tblFileAxis[1] * offset - tblRankAxis[1] * shift
  ];
  let reader = gameOver !== "" ? 1 : colour;
  if (tblColourIsBot(reader) && !tblColourIsBot(-reader)) reader = -reader;
  // At yaw 0 text reads upright from +Z; turn it to read from the reader's side of the board.
  const yaw = (Math.atan2(-tblRankAxis[0] * reader, -tblRankAxis[1] * reader) * 180) / Math.PI;
  world.setTextLabel({
    id: TBL_LABEL_ID,
    text: line + "\n" + last,
    position,
    rotationY: yaw,
    size: Math.max(0.04, tblSquareSize * 0.32),
    color: "#f8fafc",
    background: "#111827"
  });
}

// ---------------------------------------------------------------- moving pieces ------

function tblRestingPosition(square: TblSquare, code: number): Vec3 {
  const template = tblTemplates[tblTemplateKey(code)];
  const lift = template ? template.lift : 0.04;
  return [square.position[0], square.position[1] + lift + TBL_DROP, square.position[2]];
}

/**
 * Where a captured piece goes: the capture zone on the capturer's half of the table (it arranges
 * what it holds), or - when that seat's zones are not out, as on a table where nobody sits
 * there - spot `index` of a two-wide row beside the board's h-file on the capturer's side.
 */
async function tblCapturePlace(capturer: number, index: number): Promise<Vec3> {
  const name = tblSettings.captureZone.trim().toLowerCase();
  const zones = (await world.getSeatZones()).filter((zone) => zone.name.toLowerCase() === name);
  let best: SeatZoneInfo | null = null;
  let bestSide = 0;
  for (const zone of zones) {
    // How far towards the capturer's own side of the board (rank 1 for White) the zone lies.
    const side = -capturer * tblDot(tblRankAxis, zone.position[0] - tblCentre[0], zone.position[2] - tblCentre[2]);
    if (side > bestSide) {
      best = zone;
      bestSide = side;
    }
  }
  if (best) return [best.position[0], best.position[1] + 0.05, best.position[2]];
  const out = (5.2 + (index % 2) * 0.9) * tblSquareSize;
  const along = -capturer * (3.5 - Math.floor(index / 2) * 0.9) * tblSquareSize;
  return [
    tblCentre[0] + tblFileAxis[0] * out + tblRankAxis[0] * along,
    tblCentre[1] + 0.05,
    tblCentre[2] + tblFileAxis[1] * out + tblRankAxis[1] * along
  ];
}

/** How many pieces of `colour` are off the board in the game: the next free capture spot. */
function tblCapturedCount(colour: number): number {
  let onBoard = 0;
  if (game) for (const piece of game.board) if (piece * colour > 0) onBoard += 1;
  return Math.max(0, 16 - onBoard);
}

async function tblCapture(piece: TblPiece, capturer: number): Promise<void> {
  piece.handle.setPosition(await tblCapturePlace(capturer, tblCapturedCount(-capturer)));
  piece.cell = -1;
}

/** Spawn a piece from a remembered template. */
async function tblSpawn(code: number, at: Vec3): Promise<ObjectHandle | null> {
  const template = tblTemplates[tblTemplateKey(code)];
  if (!template) {
    world.broadcast("Chess: there is no " + TBL_KIND_NAMES[Math.abs(code)] + " of that colour to copy.");
    return null;
  }
  return world.spawnObject({
    kind: template.kind,
    name: template.name ?? tblTemplateKey(code),
    position: at,
    rotation: template.rotation,
    scale: template.scale,
    tags: template.tags,
    metadata: { customModelAssetId: template.model }
  });
}

/** Replace a pawn (or a promoted piece) with a piece of kind `code` on the same square. */
async function tblSwap(handle: ObjectHandle, code: number, cell: number): Promise<ObjectHandle | null> {
  if (!tblSquares) return null;
  const at = tblRestingPosition(tblSquares[cell], code);
  handle.destroy();
  return tblSpawn(code, at);
}

/**
 * Make the table show the position after `m` from `before`: whatever the mover's hands already
 * did is left alone, the rest is done here. Returns the piece a promotion made, if any.
 */
async function tblFinishMove(before: ChessState, m: ChessMove, reading: TblReading): Promise<ObjectHandle | null> {
  if (!tblSquares) return null;
  const colour = chsColourToMove(before);
  const from = chsMoveFrom(m, colour);
  const to = chsMoveTo(m, colour);
  const after = chsMakeBoard(before.board, m, colour, before.ep).board;
  const claimed = new Set<string>();
  // Find the moved piece: the mover's piece of that kind, on `to` if already moved, else on `from`.
  const takeFrom = (cells: number[], code: number): TblPiece | null => {
    for (const cell of cells) {
      for (const piece of reading.onCell[cell]) {
        if (piece.code === code && !claimed.has(piece.handle.id)) {
          claimed.add(piece.handle.id);
          return piece;
        }
      }
    }
    return null;
  };
  if (chsIsCastle(before.board, m, colour)) {
    const home = from & 56;
    const kingTo = home + (to > from ? 6 : 2);
    const rookTo = home + (to > from ? 5 : 3);
    const king = takeFrom([kingTo, to, from], colour * CHS_KING);
    const rook = takeFrom([rookTo, to], colour * CHS_ROOK);
    if (king && king.cell !== kingTo) king.handle.setPosition(tblRestingPosition(tblSquares[kingTo], colour * CHS_KING));
    if (rook && rook.cell !== rookTo) rook.handle.setPosition(tblRestingPosition(tblSquares[rookTo], colour * CHS_ROOK));
    return null;
  }
  const code = before.board[from];
  const mover = takeFrom([to, from], code);
  // Captured pieces: anything of the other colour still on `to`, or the pawn taken en passant.
  const victimCells = [to];
  if (code === colour * CHS_PAWN && to === before.ep && before.board[to] === 0) victimCells.push(to - (colour === 1 ? 8 : -8));
  for (const cell of victimCells) {
    for (const piece of reading.onCell[cell].slice()) {
      if (piece.code * colour < 0) await tblCapture(piece, colour);
    }
  }
  if (!mover) return null;
  if (after[to] !== code) return tblSwap(mover.handle, after[to], to);
  mover.handle.setPosition(tblRestingPosition(tblSquares[to], code));
  return null;
}

/** After any move: note the ending, save, redraw the status. */
async function tblAfterMove(): Promise<void> {
  if (!game) return;
  if (gameOver === "") {
    const ending = chsEnding(game);
    if (ending !== "") {
      gameOver = ending;
      world.broadcast("Game over. " + tblEndingLine());
    }
  }
  await tblSave();
  tblRenderStatus();
}

/** Play `m` for the side to move: finish it on the table, record it and announce it. */
async function tblCommit(m: ChessMove, reading: TblReading, byPerson: boolean): Promise<void> {
  if (!game) return;
  const before = game;
  const colour = chsColourToMove(before);
  const san = chsSan(before, m);
  const promoted = await tblFinishMove(before, m, reading);
  game = chsApply(before, m);
  gameMoves.push(san);
  tblNoticeKey = "";
  tblPromotion = null;
  world.removeObjectMenuItem(TBL_MENU_PROMOTE + "rook");
  world.removeObjectMenuItem(TBL_MENU_PROMOTE + "bishop");
  world.removeObjectMenuItem(TBL_MENU_PROMOTE + "knight");
  if (promoted && byPerson) {
    tblPromotion = { pieceId: promoted.id, before, move: m };
    ["rook", "bishop", "knight"].forEach((kind, order) => {
      world.addObjectMenuItem({
        id: TBL_MENU_PROMOTE + kind,
        label: "Promote to a " + kind + " instead",
        match: { objectIds: [promoted.id] },
        order
      });
    });
  }
  const number = String(before.fullmove) + (colour === 1 ? ". " : "... ");
  world.broadcast(tblPlayerName(colour) + " plays " + number + san + ".");
  await world.wait(TBL_SETTLE_SECONDS);
  await tblAfterMove();
}

// ---------------------------------------------------------------- following the table -

/** Accept what the table shows as the position, keeping the side to move. */
async function tblAdopt(reading: TblReading): Promise<void> {
  if (!game) return;
  const colour = chsColourToMove(game);
  const board = tblVisible(reading, colour);
  // Castling rights survive only where king and rook still stand on their first squares.
  let castling = 0;
  if (board[4] === CHS_KING && board[7] === CHS_ROOK) castling |= game.castling & CHS_WHITE_OO;
  if (board[4] === CHS_KING && board[0] === CHS_ROOK) castling |= game.castling & CHS_WHITE_OOO;
  if (board[60] === -CHS_KING && board[63] === -CHS_ROOK) castling |= game.castling & CHS_BLACK_OO;
  if (board[60] === -CHS_KING && board[56] === -CHS_ROOK) castling |= game.castling & CHS_BLACK_OOO;
  game = {
    board,
    toPlay: game.toPlay,
    seats: [TBL_WHITE, TBL_BLACK],
    castling,
    ep: -1,
    halfmove: 0,
    fullmove: game.fullmove,
    past: [],
    keys: [],
    startpos: false
  };
  gameOver = "";
  tblNoticeKey = "";
  world.broadcast("Chess: playing on from the board as it stands, " + tblColourName(colour) + " to move.");
  await tblAfterMove();
}

/** Say something about the current table reading once, not on every drop. */
function tblNoticeOnce(key: string, message: string): void {
  if (tblNoticeKey === key) return;
  tblNoticeKey = key;
  world.broadcast(message);
}

/**
 * Compare the table with the game. A change that is one legal move for the side to move is
 * played (and finished by the script); anything else is reported and not counted.
 */
async function tblSync(actor: string | null): Promise<void> {
  if (!game || !tblSquares) return;
  const reading = await tblRead();
  const colour = chsColourToMove(game);
  const visible = tblVisible(reading, colour);
  if (tblBoardsEqual(visible, game.board)) {
    tblNoticeKey = "";
    return;
  }
  const key = visible.join(",");
  if (gameOver !== "") {
    tblNoticeOnce(key, "The game is over (" + tblEndingLine() + ") Right-click the board for a new game.");
    return;
  }
  let found: ChessMove | null = null;
  for (const m of chsLegalMoves(game)) {
    if (tblHumanOutcomes(game, m).some((outcome) => tblBoardsEqual(outcome, visible))) {
      found = m;
      break;
    }
  }
  if (found === null) {
    let movedOther = false;
    for (let cell = 0; cell < 64; cell += 1) {
      if (game.board[cell] * colour < 0 && visible[cell] !== game.board[cell]) movedOther = true;
    }
    tblNoticeOnce(key, movedOther
      ? "It is " + tblPlayerName(colour) + "'s move. Put the " + tblColourName(-colour).toLowerCase() + " piece back."
      : "That is not a legal move for " + tblColourName(colour) + " - put the piece back. (Right-click the board to use the board as it stands.)");
    return;
  }
  if (tblColourIsBot(colour)) {
    tblNoticeOnce(key, "It is " + tblPlayerName(colour) + "'s move - put the piece back.");
    return;
  }
  // Turn order: once a colour belongs to someone at the table, only they may move for it.
  const mover = gameSeatOf[tblColourKey(colour)];
  if (actor !== null && mover !== null && tblSeatOccupied(mover) && mover !== tblSeatOfPeer(actor)) {
    tblNoticeOnce(key, "It is " + tblPlayerName(colour) + "'s move - put the piece back.");
    return;
  }
  if (actor !== null) tblClaimColour(tblSeatOfPeer(actor), colour);
  await tblCommit(found, reading, true);
  const next = chsColourToMove(game);
  if (gameOver === "" && world.getTurn().enabled && tblColourIsBot(next)) {
    world.broadcast("Press End Turn to let " + tblPlayerName(next) + " move.");
  }
}

// ---------------------------------------------------------------- new game -----------

/** Put every piece on its first square: reuse what is on the table, spawn what is missing, clear extras off. */
async function tblNewGame(): Promise<void> {
  if (!tblSquares) return;
  const start = kernel.initial([TBL_WHITE, TBL_BLACK]);
  const reading = await tblRead();
  const used = new Set<string>();
  const missing: number[] = [];
  // First keep pieces already on a right square, then move the nearest spare of each kind.
  for (let cell = 0; cell < 64; cell += 1) {
    const want = start.board[cell];
    if (want === 0) continue;
    const here = reading.onCell[cell].find((piece) => piece.code === want && !used.has(piece.handle.id));
    if (here) used.add(here.handle.id);
    else missing.push(cell);
  }
  const spawnLater: number[] = [];
  for (const cell of missing) {
    const want = start.board[cell];
    const square = tblSquares[cell];
    let best: TblPiece | null = null;
    for (const piece of reading.pieces) {
      if (piece.code !== want || used.has(piece.handle.id)) continue;
      if (!best || tblPlanDistance(piece.handle.position, square.position) < tblPlanDistance(best.handle.position, square.position)) best = piece;
    }
    if (best) {
      used.add(best.handle.id);
      best.handle.setPosition(tblRestingPosition(square, want));
    } else {
      spawnLater.push(cell);
    }
  }
  // Pieces a promotion made, or any extras on the board, go beside the board like captures.
  const extras: Record<number, number> = { 1: 0, [-1]: 0 };
  for (const piece of reading.pieces) {
    if (used.has(piece.handle.id) || piece.cell < 0) continue;
    const colour = piece.code > 0 ? 1 : -1;
    piece.handle.setPosition(await tblCapturePlace(-colour, extras[colour]));
    extras[colour] += 1;
  }
  for (const cell of spawnLater) {
    await tblSpawn(start.board[cell], tblRestingPosition(tblSquares[cell], start.board[cell]));
  }
  game = start;
  gameOver = "";
  gameMoves = [];
  tblNoticeKey = "";
  tblPromotion = null;
  gameSeatOf[TBL_WHITE] = null;
  gameSeatOf[TBL_BLACK] = null;
  tblClaimColour(null, 1);
  await world.wait(TBL_SETTLE_SECONDS);
  world.broadcast("New chess game. Whoever moves first plays White.");
  await tblAfterMove();
}

// ---------------------------------------------------------------- start up -----------

async function tblEnsureReady(): Promise<boolean> {
  if (tblSquares && game) return true;
  const saved = await tblLoadSaved();
  if (!tblSquares && !(await tblLoadSquares(saved ? { file: saved.file, rank: saved.rank } : null))) return false;
  if (game) return true;
  if (saved) {
    for (const key of Object.keys(saved.templates || {})) tblTemplates[key] = saved.templates[key];
    game = saved.game;
    gameOver = saved.over || "";
    gameMoves = Array.isArray(saved.moves) ? saved.moves : [];
    gameSeatOf[TBL_WHITE] = saved.white;
    gameSeatOf[TBL_BLACK] = saved.black;
    await tblRead();
    await tblSync(null);
    tblRenderStatus();
    return true;
  }
  // No game saved on this table: set the pieces out for a new one.
  await tblRead();
  await tblNewGame();
  return game !== null;
}

// ---------------------------------------------------------------- bots ---------------

type BotChooser = (state: ChessState, difficultyId: string | null, signal: BotAbortSignal | undefined) => Promise<ChessMove>;

function botMinimax(state: ChessState, difficultyId: string | null): ChessMove {
  const level = difficultyId !== null && BOT_MINIMAX[difficultyId] !== undefined ? BOT_MINIMAX[difficultyId] : BOT_MINIMAX["normal"];
  return chsMinimaxMove(state, level.depth, level.noise, tblRandom);
}

/** Every bot this script can play, by HANDLER id (each bot's manifest id is kept equal to it). */
const BOT_CHOOSERS: Record<string, BotChooser> = {
  minimax: async (state, difficultyId) => botMinimax(state, difficultyId),
  maia: async (state, difficultyId, signal) => {
    const level = difficultyId !== null && BOT_MAIA[difficultyId] !== undefined ? BOT_MAIA[difficultyId] : BOT_MAIA["medium"];
    try {
      const inputs: Record<string, AiTensor> = {};
      inputs[BOT_MAIA_INPUT] = kernel.encode(state);
      const outputs = await ai.evaluate(level.modelId, inputs, { signal });
      const plies = (state.fullmove - 1) * 2 + (chsColourToMove(state) === 1 ? 0 : 1);
      const temperature = plies < BOT_OPENING_PLIES && state.startpos ? BOT_OPENING_TEMPERATURE : 0;
      return chsMoveFromPolicy(state, outputs[BOT_MAIA_POLICY], temperature, tblRandom);
    } catch (error) {
      // This host cannot run the network (or it failed): play Minimax at the matching strength.
      world.log("Chess: Maia could not run here (" + tblDescribe(error) + "); playing Minimax instead.");
      const fallback: Record<string, string> = { easy: "easy", medium: "normal", hard: "hard" };
      return botMinimax(state, difficultyId !== null && fallback[difficultyId] ? fallback[difficultyId] : "normal");
    }
  }
};

/** A bot plays `m` for the side to move. */
async function tblBotPlay(m: ChessMove): Promise<void> {
  const reading = await tblRead();
  await tblCommit(m, reading, false);
}

/**
 * One bot turn: catch up with the table, then choose and play. The table ends the bot's turn
 * when this resolves; a throw makes it skip the turn with a notice.
 */
async function botTakeTurn(ctx: BotTurnContext, chooser: BotChooser): Promise<void> {
  await tblRun(async () => {
    if (!(await tblEnsureReady()) || !game) throw new Error("the board is not set up (see the chat).");
    await tblSync(null);
    if (gameOver !== "") return;
    const colour = tblColourOfSeat(ctx.seat);
    if (colour === 0) throw new Error("this bot's seat plays neither colour.");
    if (chsColourToMove(game) !== colour) {
      world.broadcast("Waiting for " + tblPlayerName(-colour) + " to move.");
      return;
    }
    const move = await chooser(game, ctx.difficultyId, ctx.signal);
    if (ctx.signal.aborted) return;
    await tblBotPlay(move);
  });
}

bots.register({ id: "minimax", onTurn: (ctx) => botTakeTurn(ctx, BOT_CHOOSERS["minimax"]) });
bots.register({ id: "maia", onTurn: (ctx) => botTakeTurn(ctx, BOT_CHOOSERS["maia"]) });

/**
 * With turn mode off (every solo table), nobody calls a bot's `onTurn`, so the script plays its
 * seated bots itself whenever the side to move belongs to a bot. Two bots and nobody who has
 * moved yet: the first seated bot takes White. One bot: it waits for the person's first move
 * (which makes them White) unless the person has taken Black with the settings.
 */
async function botDriveSeatedBots(): Promise<void> {
  for (let guard = 0; guard < 600; guard += 1) {
    if (!game || gameOver !== "" || world.getTurn().enabled) return;
    const seatedBots = world.getPlayers().filter((player) => player.isBot && player.seat !== null);
    if (seatedBots.length === 0) return;
    if (gameSeatOf[TBL_WHITE] === null && gameSeatOf[TBL_BLACK] === null && seatedBots.length >= 2) {
      gameSeatOf[TBL_WHITE] = seatedBots[0].seat;
      gameSeatOf[TBL_BLACK] = seatedBots[1].seat;
    }
    const colour = chsColourToMove(game);
    const seat = gameSeatOf[tblColourKey(colour)];
    const player = seatedBots.find((entry) => entry.seat === seat);
    if (!player) return;
    const chooser = player.botId !== null ? BOT_CHOOSERS[player.botId] : undefined;
    if (!chooser) {
      world.broadcast("Chess: this script has no bot called \"" + String(player.botId) + "\".");
      return;
    }
    await world.wait(BOT_PACE_SECONDS);
    if (!game || gameOver !== "") return;
    await tblBotPlay(await chooser(game, player.difficultyId, undefined));
  }
}

function botKick(): void {
  void tblRun(async () => {
    if (await tblEnsureReady()) await botDriveSeatedBots();
  });
}

// ---------------------------------------------------------------- people --------------

function tblIsPiece(object: ObjectData): boolean {
  const tag = tblSettings.pieceTag.trim();
  return (tag.length === 0 || object.tags.indexOf(tag) >= 0) && tblCodeOf(object.tags) !== 0;
}

globalEvents.onObjectDropped.add((object, context) => {
  if (context.actor === "Script" || !tblIsPiece(object)) return;
  void tblRun(async () => {
    if (!(await tblEnsureReady())) return;
    await world.wait(TBL_SETTLE_SECONDS);
    await tblSync(context.actor);
    await botDriveSeatedBots();
  });
});

globalEvents.onPlayerJoined.add(() => botKick());
globalEvents.onSeatChanged.add(() => botKick());

world.addObjectMenuItem({ id: TBL_MENU_NEW_GAME, label: "New chess game", match: { kinds: ["board"] }, order: 0 });
world.addObjectMenuItem({ id: TBL_MENU_ADOPT, label: "Use the board as it stands", match: { kinds: ["board"] }, order: 1 });
world.addObjectMenuItem({ id: TBL_MENU_RESIGN, label: "Resign", match: { kinds: ["board"] }, order: 2, danger: true });

globalEvents.onObjectMenuItem.add((object, itemId, context) => {
  void tblRun(async () => {
    if (itemId === TBL_MENU_NEW_GAME) {
      if (!tblSquares && !(await tblEnsureReady())) return;
      await tblNewGame();
      await botDriveSeatedBots();
      return;
    }
    if (!(await tblEnsureReady()) || !game) return;
    if (itemId === TBL_MENU_ADOPT) {
      await tblAdopt(await tblRead());
      await botDriveSeatedBots();
      return;
    }
    if (itemId === TBL_MENU_RESIGN) {
      if (gameOver !== "") return;
      const seat = tblSeatOfPeer(context.actor);
      let colour = gameSeatOf[TBL_WHITE] === seat ? 1 : gameSeatOf[TBL_BLACK] === seat ? -1 : 0;
      if (colour === 0) colour = chsColourToMove(game);
      gameOver = colour === 1 ? "resigned-white" : "resigned-black";
      world.broadcast(tblEndingLine());
      await tblAfterMove();
      return;
    }
    if (itemId.indexOf(TBL_MENU_PROMOTE) === 0 && tblPromotion && tblPromotion.pieceId === object.id) {
      const kind = itemId.slice(TBL_MENU_PROMOTE.length);
      const promo = kind === "rook" ? 2 : kind === "bishop" ? 3 : 0;
      const before = tblPromotion.before;
      const colour = chsColourToMove(before);
      const move = chsWithPromo(tblPromotion.move, promo);
      const to = chsMoveTo(move, colour);
      const replaced = await tblSwap(object, colour * chsPromotionPiece(move), to);
      game = chsApply(before, move);
      gameMoves[gameMoves.length - 1] = chsSan(before, move);
      gameOver = "";
      tblPromotion = replaced ? { pieceId: replaced.id, before, move } : null;
      for (const other of ["rook", "bishop", "knight"]) world.removeObjectMenuItem(TBL_MENU_PROMOTE + other);
      world.broadcast(tblPlayerName(colour) + " promotes to a " + kind + " instead: " + gameMoves[gameMoves.length - 1] + ".");
      await tblAfterMove();
    }
