async function tblFinishMove(before, m, reading) {
    if (!tblSquares)
        return null;
    const colour = chsColourToMove(before);
    const from = chsMoveFrom(m, colour);
    const to = chsMoveTo(m, colour);
    const after = chsMakeBoard(before.board, m, colour, before.ep).board;
    const claimed = new Set();
    // Find the moved piece: the mover's piece of that kind, on `to` if already moved, else on `from`.
    const takeFrom = (cells, code) => {
        for (const cell of cells) {
            for (const piece of reading.onCell[cell]) {
                if (piece.code === code && !claimed.has(piece.handle.id)) {
                    claimed.add(piece.handle.id);
                    return piece;
                }
            }
        }
        return null;
    };
    if (chsIsCastle(before.board, m, colour)) {
        const home = from & 56;
        const kingTo = home + (to > from ? 6 : 2);
        const rookTo = home + (to > from ? 5 : 3);
        const king = takeFrom([kingTo, to, from], colour * CHS_KING);
        const rook = takeFrom([rookTo, to], colour * CHS_ROOK);
        if (king && king.cell !== kingTo)
            king.handle.setPosition(tblRestingPosition(tblSquares[kingTo], colour * CHS_KING));
        if (rook && rook.cell !== rookTo)
            rook.handle.setPosition(tblRestingPosition(tblSquares[rookTo], colour * CHS_ROOK));
        return null;
    }
    const code = before.board[from];
    const mover = takeFrom([to, from], code);
    // Captured pieces: anything of the other colour still on `to`, or the pawn taken en passant.
    const victimCells = [to];
    if (code === colour * CHS_PAWN && to === before.ep && before.board[to] === 0)
        victimCells.push(to - (colour === 1 ? 8 : -8));
    for (const cell of victimCells) {
        for (const piece of reading.onCell[cell].slice()) {
            if (piece.code * colour < 0)
                await tblCapture(piece, colour);
        }
    }
