async function tblSync(actor) {
    if (!game || !tblSquares)
        return;
    const reading = await tblRead();
    const colour = chsColourToMove(game);
    const visible = tblVisible(reading, colour);
    if (tblBoardsEqual(visible, game.board)) {
        tblNoticeKey = "";
        return;
    }
    const key = visible.join(",");
    if (gameOver !== "") {
        tblNoticeOnce(key, "The game is over (" + tblEndingLine() + ") Right-click the board for a new game.");
        return;
    }
    let found = null;
    for (const m of chsLegalMoves(game)) {
        if (tblHumanOutcomes(game, m).some((outcome) => tblBoardsEqual(outcome, visible))) {
            found = m;
            break;
        }
    }
    if (found === null) {
        let movedOther = false;
        for (let cell = 0; cell < 64; cell += 1) {
            if (game.board[cell] * colour < 0 && visible[cell] !== game.board[cell])
                movedOther = true;
        }
        tblNoticeOnce(key, movedOther
            ? "It is " + tblPlayerName(colour) + "'s move. Put the " + tblColourName(-colour).toLowerCase() + " piece back."
            : "That is not a legal move for " + tblColourName(colour) + " - put the piece back. (Right-click the board to use the board as it stands.)");
        return;
    }
    if (tblColourIsBot(colour)) {
        tblNoticeOnce(key, "It is " + tblPlayerName(colour) + "'s move - put the piece back.");
        return;
    }
    // Turn order: once a colour belongs to someone at the table, only they may move for it.
    const mover = gameSeatOf[tblColourKey(colour)];
    if (actor !== null && mover !== null && tblSeatOccupied(mover) && mover !== tblSeatOfPeer(actor)) {
        tblNoticeOnce(key, "It is " + tblPlayerName(colour) + "'s move - put the piece back.");
        return;
    }
    if (actor !== null)
        tblClaimColour(tblSeatOfPeer(actor), colour);
    await tblCommit(found, reading, true);
    const next = chsColourToMove(game);
