// ---------------------------------------------------------------- new game -----------
/** Put every piece on its first square: reuse what is on the table, spawn what is missing, clear extras off. */
async function tblNewGame() {
    if (!tblSquares)
        return;
    const start = kernel.initial([TBL_WHITE, TBL_BLACK]);
    const reading = await tblRead();
    const used = new Set();
    const missing = [];
    // First keep pieces already on a right square, then move the nearest spare of each kind.
    for (let cell = 0; cell < 64; cell += 1) {
        const want = start.board[cell];
        if (want === 0)
            continue;
        const here = reading.onCell[cell].find((piece) => piece.code === want && !used.has(piece.handle.id));
        if (here)
            used.add(here.handle.id);
        else
            missing.push(cell);
    }
    const spawnLater = [];
    for (const cell of missing) {
        const want = start.board[cell];
        const square = tblSquares[cell];
        let best = null;
        for (const piece of reading.pieces) {
            if (piece.code !== want || used.has(piece.handle.id))
                continue;
            if (!best || tblPlanDistance(piece.handle.position, square.position) < tblPlanDistance(best.handle.position, square.position))
                best = piece;
        }
        if (best) {
            used.add(best.handle.id);
            best.handle.setPosition(tblRestingPosition(square, want));
        }
        else {
            spawnLater.push(cell);
        }
    }
    // Pieces a promotion made, or any extras on the board, go beside the board like captures.
    const extras = { 1: 0, [-1]: 0 };
    for (const piece of reading.pieces) {
        if (used.has(piece.handle.id) || piece.cell < 0)
            continue;
        const colour = piece.code > 0 ? 1 : -1;
        piece.handle.setPosition(await tblCapturePlace(-colour, extras[colour]));
        extras[colour] += 1;
    }
    for (const cell of spawnLater) {
        await tblSpawn(start.board[cell], tblRestingPosition(tblSquares[cell], start.board[cell]));
    }
    game = start;
    gameOver = "";
    gameMoves = [];
    tblNoticeKey = "";
    tblPromotion = null;
    gameSeatOf[TBL_WHITE] = null;
    gameSeatOf[TBL_BLACK] = null;
    tblClaimColour(null, 1);
    await world.wait(TBL_SETTLE_SECONDS);
    world.broadcast("New chess game. Whoever moves first plays White.");
    await tblAfterMove();
}
// ---------------------------------------------------------------- start up -----------
async function tblEnsureReady() {
    if (tblSquares && game)
        return true;
    const saved = await tblLoadSaved();
    if (!tblSquares && !(await tblLoadSquares(saved ? { file: saved.file, rank: saved.rank } : null)))
        return false;
    if (game)
        return true;
    if (saved) {
        for (const key of Object.keys(saved.templates || {}))
            tblTemplates[key] = saved.templates[key];
        game = saved.game;
        gameOver = saved.over || "";
        gameMoves = Array.isArray(saved.moves) ? saved.moves : [];
        gameSeatOf[TBL_WHITE] = saved.white;
        gameSeatOf[TBL_BLACK] = saved.black;
        await tblRead();
        await tblSync(null);
        tblRenderStatus();
        return true;
    }
    // No game saved on this table: set the pieces out for a new one.
    await tblRead();
    await tblNewGame();
