/**
 * With turn mode off (every solo table), nobody calls a bot's `onTurn`, so the script plays its
 * seated bots itself whenever the side to move belongs to a bot. Two bots and nobody who has
 * moved yet: the first seated bot takes White. One bot: it waits for the person's first move
 * (which makes them White) unless the person has taken Black with the settings.
 */
async function botDriveSeatedBots() {
    for (let guard = 0; guard < 600; guard += 1) {
        if (!game || gameOver !== "" || world.getTurn().enabled)
            return;
        const seatedBots = world.getPlayers().filter((player) => player.isBot && player.seat !== null);
        if (seatedBots.length === 0)
            return;
        if (gameSeatOf[TBL_WHITE] === null && gameSeatOf[TBL_BLACK] === null && seatedBots.length >= 2) {
            gameSeatOf[TBL_WHITE] = seatedBots[0].seat;
            gameSeatOf[TBL_BLACK] = seatedBots[1].seat;
        }
        const colour = chsColourToMove(game);
        const seat = gameSeatOf[tblColourKey(colour)];
        const player = seatedBots.find((entry) => entry.seat === seat);
        if (!player)
            return;
        const chooser = player.botId !== null ? BOT_CHOOSERS[player.botId] : undefined;
        if (!chooser) {
            world.broadcast("Chess: this script has no bot called \"" + String(player.botId) + "\".");
            return;
        }
        await world.wait(BOT_PACE_SECONDS);
        if (!game || gameOver !== "")
            return;
        await tblBotPlay(await chooser(game, player.difficultyId, undefined));
    }
}
function botKick() {
    void tblRun(async () => {
        if (await tblEnsureReady())
            await botDriveSeatedBots();
    });
}
// ---------------------------------------------------------------- people --------------
function tblIsPiece(object) {
    const tag = tblSettings.pieceTag.trim();
    return (tag.length === 0 || object.tags.indexOf(tag) >= 0) && tblCodeOf(object.tags) !== 0;
}
globalEvents.onObjectDropped.add((object, context) => {
    if (context.actor === "Script" || !tblIsPiece(object))
        return;
    void tblRun(async () => {
        if (!(await tblEnsureReady()))
            return;
        await world.wait(TBL_SETTLE_SECONDS);
        await tblSync(context.actor);
        await botDriveSeatedBots();
    });
});
globalEvents.onPlayerJoined.add(() => botKick());
globalEvents.onSeatChanged.add(() => botKick());
world.addObjectMenuItem({ id: TBL_MENU_NEW_GAME, label: "New chess game", match: { kinds: ["board"] }, order: 0 });
world.addObjectMenuItem({ id: TBL_MENU_ADOPT, label: "Use the board as it stands", match: { kinds: ["board"] }, order: 1 });
world.addObjectMenuItem({ id: TBL_MENU_RESIGN, label: "Resign", match: { kinds: ["board"] }, order: 2, danger: true });
globalEvents.onObjectMenuItem.add((object, itemId, context) => {
    void tblRun(async () => {
        if (itemId === TBL_MENU_NEW_GAME) {
            if (!tblSquares && !(await tblEnsureReady()))
                return;
            await tblNewGame();
            await botDriveSeatedBots();
            return;
        }
        if (!(await tblEnsureReady()) || !game)
            return;
        if (itemId === TBL_MENU_ADOPT) {
            await tblAdopt(await tblRead());
            await botDriveSeatedBots();
            return;
        }
        if (itemId === TBL_MENU_RESIGN) {
            if (gameOver !== "")
                return;
            const seat = tblSeatOfPeer(context.actor);
            let colour = gameSeatOf[TBL_WHITE] === seat ? 1 : gameSeatOf[TBL_BLACK] === seat ? -1 : 0;
            if (colour === 0)
                colour = chsColourToMove(game);
            gameOver = colour === 1 ? "resigned-white" : "resigned-black";
            world.broadcast(tblEndingLine());
            await tblAfterMove();
            return;
        }
        if (itemId.indexOf(TBL_MENU_PROMOTE) === 0 && tblPromotion && tblPromotion.pieceId === object.id) {
            const kind = itemId.slice(TBL_MENU_PROMOTE.length);
            const promo = kind === "rook" ? 2 : kind === "bishop" ? 3 : 0;
            const before = tblPromotion.before;
            const colour = chsColourToMove(before);
            const move = chsWithPromo(tblPromotion.move, promo);
            const to = chsMoveTo(move, colour);
            const replaced = await tblSwap(object, colour * chsPromotionPiece(move), to);
            game = chsApply(before, move);
            gameMoves[gameMoves.length - 1] = chsSan(before, move);
            gameOver = "";
            tblPromotion = replaced ? { pieceId: replaced.id, before, move } : null;
            for (const other of ["rook", "bishop", "knight"])
                world.removeObjectMenuItem(TBL_MENU_PROMOTE + other);
            world.broadcast(tblPlayerName(colour) + " promotes to a " + kind + " instead: " + gameMoves[gameMoves.length - 1] + ".");
            await tblAfterMove();
        }
    });
});
void tblRun(async () => {
    if (!(await tblEnsureReady()))
        return;
    world.log("Chess ready.");
    await botDriveSeatedBots();
});
